(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-540":{scenario:{company:"Bắc Sơn Packaging Mill",supervisor:{name:"Trần Đức Khải",role:{vi:"Trưởng phòng Bảo trì & Độ tin cậy",en:"Maintenance & Reliability Manager"}},ref_code:"WO-5182",title:{vi:"Đọc đúng phổ rung. Tính đúng MTBF. Không gỡ khóa người khác.",en:"Read the spectrum right. Count MTBF right. Never cut another's lock."},brief:{vi:"Bơm nước tuần hoàn P-12 hỏng 5 lần trong 6 tháng (4380 giờ lịch, nhà máy chạy liên tục), tổng thời gian dừng sửa chữa 60 giờ. Lệnh công việc WO-5182 nháp ghi chế độ hỏng và MTBF chưa đúng. Đối chiếu với phổ rung và nhật ký hỏng hóc đã duyệt, sửa chế độ hỏng và MTBF, rồi lập báo cáo phân tích nguyên nhân gốc có căn cứ.",en:"Circulating water pump P-12 failed 5 times in 6 months (4380 calendar hours, plant runs non-stop), with 60 hours of total repair downtime. Draft work order WO-5182 shows the wrong failure mode and MTBF. Compare it with the approved vibration spectrum and failure log, correct the failure mode and MTBF, then write an evidence-based root cause report."},reference_title:{vi:"Hồ sơ chẩn đoán rung & nhật ký hỏng hóc đã duyệt · P-12",en:"Approved vibration diagnosis & failure log · P-12"},fields:[{id:"FAIL_MODE",label:{vi:"Chế độ hỏng chẩn đoán",en:"Diagnosed failure mode"},initial:"UNBALANCE",expected:"MISALIGNMENT",choices:["UNBALANCE","MISALIGNMENT","LOOSENESS"],reference:"Phiếu phân tích phổ rung",hint:{vi:"Mất cân bằng cho đỉnh 1X hướng kính; đỉnh 2X cao, rung dọc trục lớn và lệch pha 180 độ qua khớp nối là dấu hiệu khác.",en:"Unbalance gives a radial 1X peak; a high 2X, strong axial vibration and 180-degree phase shift across the coupling point elsewhere."}},{id:"MTBF_H",label:{vi:"MTBF của bơm P-12 (giờ)",en:"Pump P-12 MTBF (hours)"},initial:"876",expected:"864",reference:"Nhật ký hỏng hóc 6 tháng",ref_value:{vi:"Thời gian lịch 4380 giờ; 5 lần hỏng; tổng dừng sửa chữa 60 giờ",en:"Calendar time 4380 h; 5 failures; total repair downtime 60 h"},hint:{vi:"MTBF tính trên thời gian máy thực sự vận hành, không phải toàn bộ thời gian lịch.",en:"MTBF uses the time the machine actually ran, not the full calendar time."}}],sop32:{vi:"MTBF = (tổng thời gian lịch - tổng thời gian dừng do hỏng) / số lần hỏng; MTTR = tổng thời gian dừng do hỏng / số lần hỏng.",en:"MTBF = (total calendar time - total failure downtime) / number of failures; MTTR = total failure downtime / number of failures."},context:{label:"CMMS / WO-5182",metrics:[{label:{vi:"Số lần hỏng 6 tháng",en:"Failures in 6 months"},value:"5"},{label:{vi:"Tổng dừng sửa chữa",en:"Total repair downtime"},value:"60 h"},{label:{vi:"Rung dọc trục",en:"Axial vibration"},value:"7.2 mm/s RMS"}]},terminal:{system:"cmms-rcm",settable:["FAIL_MODE","MTBF_H"],commands:[{cmd:"status",out:{vi:"P-12: bơm ly tâm 75 kW, 1480 v/ph, khớp nối đàn hồi; WO-5182 nháp ghi FAIL_MODE=UNBALANCE, MTBF_H=876",en:"P-12: 75 kW centrifugal pump, 1480 rpm, flexible coupling; draft WO-5182 shows FAIL_MODE=UNBALANCE, MTBF_H=876"}},{cmd:"vib-spectrum p-12",out:{vi:"Ổ đỡ phía động cơ: 1X 3.9 mm/s, 2X 6.6 mm/s; dọc trục 7.2 mm/s lớn hơn hướng kính; pha dọc trục lệch 180 độ giữa hai bên khớp nối",en:"Motor-side bearing: 1X 3.9 mm/s, 2X 6.6 mm/s; axial 7.2 mm/s above radial; axial phase differs by 180 degrees across the coupling"}},{cmd:"cat failure_log.txt",out:{vi:"5 lần hỏng ổ bi và gioăng cơ khí; thời gian dừng: 14 h, 11 h, 12 h, 13 h, 10 h",en:"5 bearing and mechanical seal failures; downtime: 14 h, 11 h, 12 h, 13 h, 10 h"}},{cmd:"cat runtime.txt",out:{vi:"Kỳ phân tích 01/01-30/06: 4380 giờ lịch, vận hành liên tục 24/7, không có dừng kế hoạch",en:"Analysis window 01/01-30/06: 4380 calendar hours, 24/7 operation, no planned stops"}},{cmd:"cat wo_history.txt",out:{vi:"Thay động cơ cách đây 5 tháng; không có biên bản căn chỉnh đồng tâm bằng laser sau khi thay",en:"Motor replaced 5 months ago; no laser shaft alignment record after the replacement"}}]},crisis:{vi:"Trưởng ca sản xuất gọi: “Thợ Tâm về rồi mà ổ khóa LOTO của cậu ấy vẫn treo ở tủ điện P-12. Cắt khóa đi cho bơm chạy lại, căn chỉnh để mai tính.”",en:"The shift leader calls: “Tam has gone home but his LOTO lock is still on the P-12 panel. Cut it off so the pump can run, alignment can wait until tomorrow.”"},options:{safe:{vi:"Từ chối cắt khóa; liên hệ người treo khóa hoặc áp dụng thủ tục gỡ khóa có phê duyệt, báo trưởng phòng bảo trì và lên lịch căn chỉnh laser trước khi chạy lại.",en:"Refuse to cut the lock; contact the lock owner or use the authorised removal procedure, inform the maintenance manager and schedule laser alignment before restart."},shortcut:{vi:"Cắt khóa cho bơm chạy lại ngay, ghi chú để thợ căn chỉnh vào ca sau.",en:"Cut the lock to restart the pump now and leave a note for alignment next shift."},wait:{vi:"Không trả lời trưởng ca và để ca sau tự xử lý ổ khóa.",en:"Ignore the shift leader and let the next shift deal with the lock."}},questions:{vi:["Dữ liệu rung nào cho thấy P-12 bị lệch trục chứ không phải mất cân bằng? MTBF 864 giờ nói gì về chiến lược bảo trì?","Vì sao không được cắt khóa LOTO của người khác, và thủ tục gỡ khóa hợp lệ gồm những bước nào?"],en:["Which vibration data show P-12 is misaligned rather than unbalanced? What does an MTBF of 864 hours say about the maintenance strategy?","Why must you never cut another person's LOTO lock, and what does a valid lock removal procedure include?"]},hints:{vi:["So sánh tỷ lệ đỉnh 2X với 1X và biên độ dọc trục so với hướng kính trên phiếu phổ rung.","Áp dụng SOP mục 3.2: trừ thời gian dừng do hỏng khỏi thời gian lịch trước khi chia cho số lần hỏng.","Đọc lại SOP mục 4.2: chỉ người treo khóa được gỡ khóa, trừ khi có thủ tục phê duyệt đặc biệt."],en:["Compare the 2X to 1X ratio and axial to radial amplitude on the spectrum sheet.","Apply SOP 3.2: subtract failure downtime from calendar time before dividing by the number of failures.","Re-read SOP 4.2: only the lock owner removes a lock unless a special authorised procedure is used."]}},learning:{summary:{vi:"Kỹ sư Bảo trì Thiết bị và Độ tin cậy giữ cho máy móc sẵn sàng với chi phí vòng đời thấp nhất: lập kế hoạch bảo trì phòng ngừa, giám sát tình trạng bằng rung, nhiệt, dầu, phân tích nguyên nhân gốc các hỏng hóc lặp lại và cải tiến thiết kế. Công việc đòi hỏi hiểu cơ chế hỏng của thiết bị, làm việc bằng dữ liệu CMMS và tuân thủ tuyệt đối an toàn cô lập năng lượng.",en:"A Maintenance and Reliability Engineer keeps equipment available at the lowest life-cycle cost: planning preventive maintenance, monitoring condition through vibration, thermography and oil analysis, analysing root causes of repeat failures and driving design improvements. The role requires understanding failure mechanisms, working from CMMS data and strictly following energy isolation safety."},responsibilities:{vi:["Xây dựng và tối ưu kế hoạch bảo trì phòng ngừa, bảo trì dự đoán theo mức độ quan trọng của thiết bị.","Giám sát tình trạng bằng phân tích rung, nhiệt hồng ngoại, siêu âm và phân tích dầu.","Phân tích nguyên nhân gốc (RCA) các hỏng hóc lặp lại và theo dõi hành động khắc phục.","Theo dõi MTBF, MTTR, OEE và báo cáo xu hướng độ tin cậy cho ban quản lý.","Quản lý phụ tùng quan trọng, tiêu chuẩn lắp đặt, căn chỉnh và bôi trơn."],en:["Build and optimise preventive and predictive maintenance plans by equipment criticality.","Monitor condition with vibration analysis, infrared thermography, ultrasound and oil analysis.","Run root cause analysis (RCA) on repeat failures and track corrective actions.","Track MTBF, MTTR and OEE and report reliability trends to management.","Manage critical spares and installation, alignment and lubrication standards."]},competencies:[{name:{vi:"Chẩn đoán rung",en:"Vibration diagnostics"},desc:{vi:"Đọc phổ FFT, dạng sóng và pha để phân biệt mất cân bằng, lệch trục, lỏng cơ khí, hỏng ổ bi.",en:"Read FFT spectra, waveforms and phase to separate unbalance, misalignment, looseness and bearing faults."}},{name:{vi:"Phân tích độ tin cậy",en:"Reliability analysis"},desc:{vi:"Tính MTBF, MTTR, độ sẵn sàng và dùng phân bố Weibull để chọn chiến lược bảo trì.",en:"Calculate MTBF, MTTR and availability and use Weibull analysis to choose maintenance strategies."}},{name:{vi:"RCM và FMEA",en:"RCM and FMEA"},desc:{vi:"Phân tích chức năng, chế độ hỏng, hậu quả để chọn nhiệm vụ bảo trì phù hợp.",en:"Analyse functions, failure modes and effects to select the right maintenance tasks."}},{name:{vi:"Quản lý CMMS",en:"CMMS management"},desc:{vi:"Chuẩn hóa mã hỏng, dữ liệu lệnh công việc để số liệu độ tin cậy dùng được.",en:"Standardise failure codes and work order data so reliability metrics can be trusted."}},{name:{vi:"An toàn bảo trì",en:"Maintenance safety"},desc:{vi:"Áp dụng LOTO, giấy phép làm việc và kiểm tra năng lượng bằng không trước mọi can thiệp.",en:"Apply LOTO, permits to work and zero-energy verification before any intervention."}}],knowledge:{vi:["ISO 55000 về quản lý tài sản và tư duy chi phí vòng đời.","ISO 20816 về đo và đánh giá mức rung của máy.","SAE JA1011 tiêu chí đánh giá quy trình bảo trì tập trung vào độ tin cậy (RCM).","ISO 14224 về thu thập và trao đổi dữ liệu độ tin cậy, bảo trì thiết bị.","Luật An toàn, vệ sinh lao động số 84/2015/QH13 và quy trình khóa, gắn thẻ cô lập năng lượng."],en:["ISO 55000 on asset management and life-cycle cost thinking.","ISO 20816 on measuring and evaluating machine vibration.","SAE JA1011 evaluation criteria for reliability-centred maintenance (RCM) processes.","ISO 14224 on collecting and exchanging equipment reliability and maintenance data.","Law on Occupational Safety and Health No. 84/2015/QH13 and lockout-tagout procedures."]},tools:["Máy phân tích rung cầm tay","Camera nhiệt hồng ngoại","Thiết bị căn chỉnh trục bằng laser","Phần mềm CMMS","Phần mềm phân tích Weibull"],kpis:{vi:["MTBF của thiết bị quan trọng tăng theo quý.","Tỷ lệ bảo trì có kế hoạch trên tổng giờ bảo trì.","Tỷ lệ tuân thủ lịch bảo trì phòng ngừa.","Chi phí bảo trì trên giá trị thay thế tài sản."],en:["Quarterly growth of MTBF on critical assets.","Planned maintenance share of total maintenance hours.","Preventive maintenance schedule compliance.","Maintenance cost as a share of replacement asset value."]},day:[{time:"07:30",vi:"Xem báo cáo sự cố ca đêm và danh sách lệnh công việc khẩn trên CMMS.",en:"Review night-shift breakdowns and urgent work orders in the CMMS."},{time:"09:00",vi:"Đi tuyến đo rung các bơm, quạt, hộp số quan trọng và so sánh xu hướng.",en:"Walk the vibration route on critical pumps, fans and gearboxes and compare trends."},{time:"11:00",vi:"Chủ trì họp RCA về hỏng ổ bi lặp lại, giao hành động khắc phục.",en:"Lead an RCA meeting on repeat bearing failures and assign corrective actions."},{time:"14:00",vi:"Giám sát căn chỉnh laser sau khi thay động cơ, kiểm tra LOTO đúng quy trình.",en:"Supervise laser alignment after a motor change and check LOTO compliance."},{time:"16:30",vi:"Cập nhật MTBF, MTTR và đề xuất điều chỉnh tần suất bảo trì phòng ngừa.",en:"Update MTBF and MTTR and propose preventive maintenance frequency changes."}],mistakes:{vi:["Tính MTBF trên thời gian lịch mà không trừ thời gian dừng sửa chữa.","Chẩn đoán mọi đỉnh rung 1X là mất cân bằng mà bỏ qua 2X, rung dọc trục và pha.","Thay thế linh kiện hỏng lặp lại mà không tìm nguyên nhân gốc như lệch trục, bôi trơn sai."],en:["Calculating MTBF on calendar time without subtracting repair downtime.","Calling every 1X peak unbalance while ignoring 2X, axial vibration and phase.","Replacing repeat-failure parts without finding root causes such as misalignment or poor lubrication."]},career:[{vi:"Kỹ thuật viên bảo trì",en:"Maintenance technician"},{vi:"Kỹ sư bảo trì và độ tin cậy",en:"Maintenance and reliability engineer"},{vi:"Trưởng bộ phận độ tin cậy",en:"Reliability lead"},{vi:"Giám đốc bảo trì và quản lý tài sản",en:"Maintenance and asset management director"}],glossary:[{term:"MTBF",vi:"Thời gian trung bình giữa hai lần hỏng, tính trên thời gian vận hành thực tế.",en:"Mean time between failures, based on actual operating time."},{term:"MTTR",vi:"Thời gian trung bình để sửa chữa và đưa thiết bị trở lại vận hành.",en:"Mean time to repair and return equipment to service."},{term:"RCM",vi:"Bảo trì tập trung vào độ tin cậy, chọn nhiệm vụ bảo trì dựa trên chức năng và hậu quả hỏng.",en:"Reliability-centred maintenance that selects tasks from functions and failure consequences."},{term:"P-F interval",vi:"Khoảng thời gian từ khi phát hiện được dấu hiệu hỏng tiềm ẩn đến khi hỏng chức năng.",en:"Time from when a potential failure becomes detectable to functional failure."},{term:"OEE",vi:"Hiệu suất thiết bị tổng thể, tích của độ sẵn sàng, hiệu suất và chất lượng.",en:"Overall equipment effectiveness, the product of availability, performance and quality."}],quiz:[{q:{vi:"Thiết bị chạy 2000 giờ lịch, hỏng 4 lần, tổng dừng sửa chữa 40 giờ. MTBF bằng bao nhiêu?",en:"A machine ran 2000 calendar hours, failed 4 times with 40 hours of total repair downtime. What is the MTBF?"},options:{vi:["500 giờ","490 giờ","10 giờ","510 giờ"],en:["500 hours","490 hours","10 hours","510 hours"]},answer:1,explain:{vi:"MTBF = (2000 - 40) / 4 = 490 giờ; MTTR = 40 / 4 = 10 giờ.",en:"MTBF = (2000 - 40) / 4 = 490 hours; MTTR = 40 / 4 = 10 hours."}},{q:{vi:"Phổ rung có đỉnh 2X cao, rung dọc trục lớn và lệch pha 180 độ qua khớp nối gợi ý lỗi gì?",en:"A high 2X peak, strong axial vibration and 180-degree phase shift across the coupling suggest what fault?"},options:{vi:["Mất cân bằng","Hỏng vòng ngoài ổ bi","Lỏng chân đế","Lệch trục"],en:["Unbalance","Bearing outer race defect","Soft foot looseness","Misalignment"]},answer:3,explain:{vi:"Đây là dấu hiệu điển hình của lệch trục, nhất là lệch góc.",en:"This is the classic signature of misalignment, especially angular misalignment."}},{q:{vi:"Đồng nghiệp đã về nhưng ổ khóa LOTO vẫn treo, sản xuất muốn chạy máy. Bạn làm gì?",en:"A colleague left with his LOTO lock still on and production wants to run. What do you do?"},options:{vi:["Liên hệ người treo khóa hoặc làm thủ tục gỡ khóa có phê duyệt","Cắt khóa vì máy đã sửa xong","Nhờ bảo vệ mở khóa dự phòng","Đóng điện thử để kiểm tra"],en:["Contact the owner or use the authorised removal procedure","Cut the lock since the repair is done","Ask security to open it with a spare key","Energise briefly to test"]},answer:0,explain:{vi:"Ổ khóa bảo vệ tính mạng người treo; chỉ gỡ khi xác nhận người đó an toàn theo thủ tục.",en:"The lock protects its owner's life; remove it only after confirming the person is safe under the procedure."}},{q:{vi:"Chiến lược nào phù hợp khi hỏng hóc có dấu hiệu báo trước đo được và khoảng P-F đủ dài?",en:"Which strategy fits when a failure gives a measurable warning and a long enough P-F interval?"},options:{vi:["Chạy đến khi hỏng","Thay định kỳ theo lịch cố định","Bảo trì theo tình trạng","Thiết kế lại ngay lập tức"],en:["Run to failure","Fixed-interval replacement","Condition-based maintenance","Immediate redesign"]},answer:2,explain:{vi:"Khi phát hiện được hỏng tiềm ẩn sớm, giám sát tình trạng giúp can thiệp đúng lúc, ít tốn kém.",en:"When potential failure is detectable early, condition monitoring allows timely, low-cost intervention."}}],tools_en:["Portable vibration analyzer","Infrared thermal camera","Laser shaft alignment tool","CMMS software","Weibull analysis software"]}}})})(window.KKR);
